{
  "passageId": "plastic-polymerization",
  "rules": [
    {
      "id": "R1",
      "ruleQuote": "두 원자가 각각 전자를 하나씩 내어놓아 그 두 개의 전자를 한 쌍으로 공유하면 단일 결합이라 하고, 두 쌍을 공유하면 이중 결합이라 한다.",
      "statement": "두 원자가 공유하는 전자쌍이 한 쌍이면 단일 결합이고 두 쌍이면 이중 결합이다.",
      "variables": [
        {
          "name": "두 원자가 공유하는 전자쌍의 수",
          "effect": "한 쌍이면 단일 결합, 두 쌍이면 이중 결합으로 구분된다."
        }
      ],
      "scopeQuote": null,
      "statedApplications": [
        {
          "target": "에틸렌의 탄소 원자 사이 결합과 탄소·수소 원자 사이 결합",
          "quote": "에틸렌은 두 개의 탄소 원자와 네 개의 수소 원자로 이루어지는데, 두 개의 탄소 원자가 서로 이중 결합을 하고 각각의 탄소 원자는 두 개의 수소 원자와 단일 결합을 한다."
        }
      ],
      "openSlots": []
    },
    {
      "id": "R2",
      "ruleQuote": "공유 전자쌍이 많을수록 원자 간의 결합력은 강하다.",
      "statement": "원자들이 공유하는 전자쌍의 수가 많을수록 원자 사이의 결합력이 강하다.",
      "variables": [
        {
          "name": "공유 전자쌍의 수",
          "effect": "많을수록 원자 간의 결합력이 강해진다."
        }
      ],
      "scopeQuote": null,
      "statedApplications": [],
      "openSlots": [
        {
          "id": "R2-S1",
          "target": "에틸렌의 탄소 원자 사이 이중 결합과 탄소·수소 원자 사이 단일 결합",
          "quote": "에틸렌은 두 개의 탄소 원자와 네 개의 수소 원자로 이루어지는데, 두 개의 탄소 원자가 서로 이중 결합을 하고 각각의 탄소 원자는 두 개의 수소 원자와 단일 결합을 한다.",
          "whatToDerive": "두 종류의 결합에서 공유하는 전자쌍의 수를 바탕으로 원자 간 결합력의 크기를 비교할 수 있다."
        }
      ]
    },
    {
      "id": "R3",
      "ruleQuote": "대부분의 원자는 가장 바깥 전자 껍질의 전자 수가 8개가 될 때 안정해진다.",
      "statement": "대부분의 원자는 가장 바깥 전자 껍질의 전자 수가 8개가 되면 안정해진다.",
      "variables": [
        {
          "name": "가장 바깥 전자 껍질의 전자 수",
          "effect": "8개가 될 때 원자가 안정해진다."
        }
      ],
      "scopeQuote": "대부분의 원자는",
      "statedApplications": [
        {
          "target": "다른 원자들과 전자를 공유하는 탄소 원자",
          "quote": "탄소 원자는 가장 바깥 전자 껍질에 4개의 전자를 갖고 있어, 다른 원자들과 전자를 공유하여 안정해질 수 있으며 다양한 형태의 공유 결합이 가능하여 거대한 분자의 골격을 이룰 수 있다."
        },
        {
          "target": "열을 흡수한 과산화물 개시제의 분해로 생긴 원자",
          "quote": "열을 흡수한 과산화물 개시제는 가장 바깥 껍질에 7개의 전자가 있는 불안정한 상태의 원자를 가진 분자로 분해된다."
        },
        {
          "target": "에틸렌과의 결합 후 홀로 남은 전자를 갖게 된 탄소 원자",
          "quote": "그러면 다른 쪽 탄소 원자는 공유되지 못한, 홀로 남은 전자를 갖게 된다. 이 불안정한 탄소 원자는 같은 방식으로 다른 에틸렌 분자와 반응을 하게 되고, 이와 같은 반응이 이어지며 불안정해지는 탄소 원자가 계속 생성된다."
        }
      ],
      "openSlots": []
    },
    {
      "id": "R4",
      "ruleQuote": "성장하는 두 사슬의 끝이 서로 만나 결합하여 안정한 상태가 되면 반복적인 반응이 멈추게 된다.",
      "statement": "성장하는 두 사슬의 끝이 서로 만나 결합하여 안정해지면 반복적인 중합 반응이 멈춘다.",
      "variables": [
        {
          "name": "성장하는 두 사슬 끝의 결합 및 안정화 여부",
          "effect": "두 사슬의 끝이 서로 만나 결합하여 안정한 상태가 되면 반복적인 반응이 멈춘다."
        }
      ],
      "scopeQuote": "에틸렌의 중합에는 여러 가지 방법이 있는데 그중에 하나는 과산화물 개시제를 사용하는 것이다.",
      "statedApplications": [
        {
          "target": "과산화물 개시제를 사용한 에틸렌 중합에서 성장하는 두 사슬",
          "quote": "성장하는 두 사슬의 끝이 서로 만나 결합하여 안정한 상태가 되면 반복적인 반응이 멈추게 된다."
        }
      ],
      "openSlots": []
    },
    {
      "id": "R5",
      "ruleQuote": "결정 영역이 많아질수록 플라스틱은 유연성이 낮아 충격에 약하고 가공성이 떨어지며 점점 불투명해지지만, 밀도가 높아져 단단해지고 화학 물질에 대한 민감성이 감소하며 열에 의해 잘 변형되지 않는다.",
      "statement": "플라스틱의 결정 영역 비율이 높아질수록 유연성·충격에 대한 저항성·가공성이 낮아지고 불투명해지는 한편, 밀도가 높아져 단단해지며 화학 물질에 대한 민감성과 열에 의한 변형 가능성이 낮아진다.",
      "variables": [
        {
          "name": "플라스틱에서 결정 영역이 차지하는 비율",
          "effect": "높아질수록 유연성이 낮아져 충격에 약해지고 가공성이 떨어지며 불투명해지지만, 밀도가 높아져 단단해지고 화학 물질에 대한 민감성이 감소하며 열에 의해 잘 변형되지 않는다."
        }
      ],
      "scopeQuote": null,
      "statedApplications": [],
      "openSlots": []
    }
  ]
}

